"""Small declarative workflow vocabulary generated by Codex, enforced by Bridge."""
import copy
import hashlib
import json
import re
from codex_http_bridge import BridgeError
from card_config import validate_fields

IDENT = re.compile(r'^[a-z][a-z0-9_]{0,63}$')

ARTIFACT_REFS = {'file': (), 'feishu_document': (), 'delivery': (),
                 'fcpxml': ('reference',),
                 'subtitle_manifest': ('reference', 'document'),
                 'subtitle_alignment': ('reference', 'manifest', 'document', 'output'),
                 'audio_alignment': ('alignment', 'output')}

def output_order(produced, available):
    pending = dict(produced); result = []; available = set(available)
    while pending:
        ready = [k for k, spec in pending.items()
                 if all(spec.get(ref) in available for ref in ARTIFACT_REFS.get(spec.get('kind'), ()))]
        if not ready: fail('产物校验引用存在循环或缺少输入')
        for key in ready:
            result.append(key); available.add(key); del pending[key]
    return result

def fail(message):
    raise BridgeError(400, 'invalid_workflow_definition', message)

def fingerprint(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(',', ':')).encode()).hexdigest()

def review_fields(stage, cards):
    fields={}
    form=next((c for c in cards if c['id']==stage.get('form_card')),None)
    if form:
        for action in form['actions']:fields.update(copy.deepcopy(action['fields']))
    fields.update(copy.deepcopy(stage.get('fields',{})))
    return fields

def validate_workflow(value, cards=(), allowed_users=()):
    if not isinstance(value, dict) or set(value) != {'name', 'steps'}:
        fail('流程需要名称和步骤列表')
    if not isinstance(value['name'], str) or not 1 <= len(value['name']) <= 100:
        fail('流程名称无效')
    steps=value['steps']
    if not isinstance(steps,list) or not 1 <= len(steps) <= 30:
        fail('流程需要 1 到 30 个阶段')
    ids=set();outputs=set()
    for step in steps:
        if not isinstance(step,dict) or set(step)-{'id','name','kind','prompt','needs','produces','next','revise','form_card','reviewers','fields','skills','acceptance','settings'}:
            fail('阶段字段无效')
        for field,limit in (('skills',150),('acceptance',1000)):
            if field in step and (not isinstance(step[field],list) or len(step[field])>20 or any(not isinstance(x,str) or not 1<=len(x)<=limit for x in step[field])):
                fail(field+' 必须为有限的非空文本列表')
        if 'skills' in step and (len(set(step['skills']))!=len(step['skills']) or any(not re.fullmatch(r'[A-Za-z0-9_-]+(?::[A-Za-z0-9_-]+)?',x) for x in step['skills'])):
            fail('Skill 名称无效或重复')
        if 'settings' in step and (not isinstance(step['settings'],dict) or len(step['settings'])>20 or any(not isinstance(k,str) or not 1<=len(k)<=100 or not isinstance(v,str) or not 1<=len(v)<=1000 for k,v in step['settings'].items())):
            fail('阶段参数必须为名称和文本值')
        sid=step.get('id')
        if not isinstance(sid,str) or not IDENT.fullmatch(sid) or sid in ids: fail('阶段标识无效或重复')
        ids.add(sid)
        if not isinstance(step.get('name'),str) or not 1<=len(step['name'])<=100: fail('阶段名称无效')
        if step.get('kind') not in ('agent','review'):fail('阶段类型只能为 agent 或 review')
        if not isinstance(step.get('needs',[]),list) or any(not isinstance(k,str) or not IDENT.fullmatch(k) for k in step.get('needs',[])):fail('输入名称无效')
        produced=step.get('produces',{})
        if not isinstance(produced,dict):fail('产物声明无效')
        for key,spec in produced.items():
            if not isinstance(key,str) or not IDENT.fullmatch(key) or not isinstance(spec,dict):fail('产物字段无效')
            if spec.get('kind') not in ARTIFACT_REFS:fail('不支持的产物校验类型')
            refs=ARTIFACT_REFS[spec['kind']]
            if set(spec)!={'kind',*refs}:fail('产物字段无效或缺少校验引用')
            if any(not isinstance(spec[r],str) or spec[r] not in set(step.get('needs',[]))|set(produced) for r in refs):
                fail('产物校验必须引用本阶段输入或同轮产物')
            if spec['kind']=='fcpxml' and (not isinstance(spec.get('reference'),str) or spec['reference'] not in step.get('needs',[])):
                fail('FCPXML 校验必须引用本阶段输入的原文件')
            outputs.add(key)
        output_order(produced, step.get('needs',[]))
        if step['kind']=='agent':
            if not isinstance(step.get('prompt'),str) or not 1<=len(step['prompt'])<=6000:fail('执行阶段需要业务指令')
            if not produced:fail('执行阶段须声明可校验的产物')
            if set(step)&{'revise','form_card','reviewers','fields'}:fail('审核设置只用于 review 阶段')
        else:
            if produced or not step.get('needs'):fail('审核阶段需要至少一个待审产物，不能直接生成产物')
            if 'fields' in step:
                validate_fields(step['fields'],choices=True)
                if any(s['type']!='choice' for s in step['fields'].values()):fail('审核卡当前支持固定选项')
            if step.get('form_card') and (not isinstance(step['form_card'],str) or step['form_card'] not in {c['id'] for c in cards}):fail('审核表单引用未知卡片')
            if step.get('form_card'):
                form=next(c for c in cards if c['id']==step['form_card']);fields={}
                for action in form['actions']:
                    for name,spec in action['fields'].items():
                        if spec['type']!='choice':fail('通用审核卡目前支持固定选项，请使用 choice 表单')
                        if name in fields and fields[name]!=spec:fail('审核表单的同名字段设置冲突')
                        fields[name]=spec
            reviewers=step.get('reviewers',['initiator'])
            if not isinstance(reviewers,list) or not reviewers or any(x!='initiator' and x not in allowed_users for x in reviewers):fail('审核人必须来自已授权用户')
    for s in steps:
        for edge in ('next','revise'):
            if s.get(edge) is not None and (not isinstance(s[edge],str) or s[edge] not in ids):fail('阶段指向不存在的目标')
        if any(k not in outputs for k in s.get('needs',[])):fail('阶段引用未声明的产物')
    lookup={s['id']:s for s in steps}
    if steps[0]['kind']!='agent':fail('首阶段必须生成待审核的产物')
    # The main path is sequential and must terminate. Revisions may explicitly loop back.
    for start in ids:
        seen=set();sid=start
        while sid is not None:
            if sid in seen:fail('自动前进路径不能循环；通过审核的 revise 显式退回')
            seen.add(sid);sid=lookup[sid].get('next')
    visited=set();todo=[steps[0]['id']]
    while todo:
        sid=todo.pop()
        if sid in visited:continue
        visited.add(sid);todo.extend(lookup[sid][e] for e in ('next','revise') if lookup[sid].get(e))
    if visited!=ids:fail('存在无法到达的阶段')
    # Every input must exist along the first main-path traversal, not only in a revision branch.
    available=set();sid=steps[0]['id']
    while sid:
        s=lookup[sid]
        if not set(s.get('needs',[]))<=available:fail('阶段输入在首次执行时尚未产生：'+s['name'])
        available.update(s.get('produces',{}));sid=s.get('next')
    # Definite-input analysis includes revision branches and joins.
    incoming={sid:set(outputs) for sid in ids};incoming[steps[0]['id']]=set()
    changed=True
    while changed:
        changed=False
        for s in steps:
            available=incoming[s['id']]|set(s.get('produces',{}))
            for edge in ('next','revise'):
                target=s.get(edge)
                if target:
                    common=incoming[target]&available
                    if common!=incoming[target]:incoming[target]=common;changed=True
    for s in steps:
        if not set(s.get('needs',[]))<=incoming[s['id']]:fail('某条分支缺少阶段输入：'+s['name'])
    if len(json.dumps(value,ensure_ascii=False).encode())>28000:fail('流程过长，请将详细业务步骤放入 Skill')
    return copy.deepcopy(value)

def summarize(value):
    return [{'name':s['name'],'kind':s['kind'],'needs':s.get('needs',[]),
             'skills':s.get('skills',[]),'acceptance':s.get('acceptance',[]),'settings':s.get('settings',{}),
             'outputs':list(s.get('produces',{})), 'next':s.get('next'),'revise':s.get('revise')} for s in value['steps']]
